-- NPCBots random wandering bot names, see BotDataMgr::LoadNpcBotRandomNames()
-- names from cmangos playerbots (ai_playerbot_names), gender: 0 male, 1 female
CREATE TABLE IF NOT EXISTS `creature_template_npcbot_names` (
  `id` int unsigned NOT NULL,
  `name` varchar(12) NOT NULL,
  `gender` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM `creature_template_npcbot_names`;
